import numpy as np

def maximum_cycle_mean(A: np.ndarray) -> float:
    """Compute tropical eigenvalue via Karp's algorithm."""
    n = A.shape[0]
    D = np.full((n + 1, n), -np.inf)
    D[0, :] = 0.0
    for k in range(1, n + 1):
        for i in range(n):
            D[k, i] = np.max(A[:, i] + D[k-1, :])
    lambda_star = -np.inf
    for i in range(n):
        val = np.inf
        for k in range(n):
            if D[k, i] > -np.inf and D[n, i] > -np.inf:
                val = min(val, (D[n, i] - D[k, i]) / (n - k))
        if val < np.inf:
            lambda_star = max(lambda_star, val)
    return lambda_star

A = np.array([[0.0, 3.0, -1.0], [2.0, 0.0, 1.0], [1.0, 2.0, 0.0]])
print(f"Tropical eigenvalue = {maximum_cycle_mean(A)}")

import numpy as np

def tropical_mat_map(A, x):
    return np.max(A + x[np.newaxis, :], axis=1)

def certified_iteration(A, x, k):
    """Iterate with post-fixed point certificate."""
    Tx = tropical_mat_map(A, x)
    is_postfixed = bool(np.all(x <= Tx + 1e-12))
    v = x.copy()
    for _ in range(k):
        v = tropical_mat_map(A, v)
    cert = {
        "postfixed": is_postfixed,
        "lower_bound_holds": is_postfixed and bool(np.all(x <= v + 1e-12)),
    }
    return v, cert

A = np.array([[0.5, 0.2], [0.3, 0.4]])
x = np.array([1.0, 2.0])
result, cert = certified_iteration(A, x, 10)
print(f"Result: {result}")
print(f"Certificate: {cert}")
